const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const mobileScreen=$('#mobile-screen');
const portalScreen=$('#portal-screen');
const dialog=$('#prototype-dialog');
let toastTimer;
let streetMap;
const mapLocations={
  'Dom omladine':{coords:[44.8166,20.4617],info:'Beograd · 8 slobodnih termina'},
  'Studentski kulturni centar':{coords:[44.8105,20.4663],info:'Beograd · 12 slobodnih termina'},
  'Crveni krst Zemun':{coords:[44.8463,20.4097],info:'Zemun · dolazak bez rezervacije'}
};

function showToast(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
function pill(label,type='neutral'){return `<span class="pill ${type}">${label}</span>`}
function statusTone(status){return ({Zakazan:'warning',Prijavljen:'info','Kod tima':'success','Nije došao':'neutral'})[status]||'neutral'}
function apiStatusMarkup(){const stateClass=state.api.status==='connected'?'success':state.api.status==='failed'?'warning':'neutral';const label=state.api.status==='connected'?'API povezan':state.api.status==='checking'?'Provera API-ja':state.api.status==='failed'?'Veza nije dostupna':state.api.status==='ready'?'Spremno za proveru':'API nije podešen';return `<div class="api-status"><span class="api-status-dot ${stateClass}"></span><div><strong>${label}</strong><small>${state.api.message}</small></div>${state.api.checkedAt?`<time>${state.api.checkedAt}</time>`:''}</div>`}
async function checkConfiguredApi(resource='/health'){
  if(!configuredApiBase){state.api={status:'not-configured',message:'Dodajte ?api=https://api-vasa-domena da portal čita odobreni API.',checkedAt:null};renderPortal('integrations');return}
  state.api={status:'checking',message:'Proveravamo vezu i odgovor servera…',checkedAt:null};renderPortal('integrations');
  const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),5000);
  try{const response=await fetch(`${configuredApiBase}${resource}`,{headers:{'X-Demo-Role':'admin'},signal:controller.signal});const body=await response.json();if(!response.ok)throw new Error(body?.error?.message||`HTTP ${response.status}`);state.api={status:'connected',message:resource==='/health'?'Demonstracioni API odgovara i spreman je za ugovorene rute.':'Portal ruta je odgovorila bez zdravstvenih podataka.',checkedAt:new Intl.DateTimeFormat('sr-Latn',{hour:'2-digit',minute:'2-digit'}).format(new Date())};showToast('API veza je proverena.')}catch(error){const message=error instanceof Error&&error.name==='AbortError'?'Veza je istekla — proverite javnu HTTPS API adresu i CORS pravilo.':error instanceof Error?error.message:'API nije dostupan.';state.api={status:'failed',message,checkedAt:new Intl.DateTimeFormat('sr-Latn',{hour:'2-digit',minute:'2-digit'}).format(new Date())};showToast('API nije dostupan — portal ostaje u demo režimu.')}finally{clearTimeout(timeout)}renderPortal('integrations')
}
function icon(name){const paths={bell:'<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 8h18c0-1-3-1-3-8Z"/><path d="M10 21h4"/>',arrow:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16.5 16.5 4 4"/>',settings:'<path d="M4 6h10M18 6h2M4 12h3M11 12h9M4 18h8M16 18h4"/><circle cx="16" cy="6" r="2"/><circle cx="9" cy="12" r="2"/><circle cx="14" cy="18" r="2"/>',card:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/>',heart:'<path d="M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.4 2.4 0 1 1 3.5 2.1c-1 .5-1.3 1-1.3 2M12 17h.01"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.heart}</svg>`}
function mobileHeader(title,back='home',action=''){return `<header class="mobile-page-header"><button class="back-button" data-mobile-screen="${back}" aria-label="Nazad">${icon('arrow')}</button><h2>${title}</h2>${action||'<span style="width:40px"></span>'}</header>`}
function eventCard(name,city,date='12',day='SUB',time='10:00-14:00',screen='action-detail'){return `<button class="event-card" data-mobile-screen="${screen}"><span class="date-tile"><span>${day}</span><strong>${date}</strong><span>OKT</span></span><span class="event-info"><strong>${name}</strong><span>${city}</span><span>${time}</span></span><span class="chevron">›</span></button>`}
function qrCode(){const size=21;const inFinder=(row,col)=>[[0,0],[0,14],[14,0]].some(([top,left])=>row>=top&&row<top+7&&col>=left&&col<left+7);const finder=(row,col)=>{const local=[row%7,col%7];return local[0]===0||local[0]===6||local[1]===0||local[1]===6||(local[0]>=2&&local[0]<=4&&local[1]>=2&&local[1]<=4)};return `<div class="qr-code" role="img" aria-label="Jednokratni QR kod za identifikaciju">${Array.from({length:size*size},(_,index)=>{const row=Math.floor(index/size),col=index%size;const filled=inFinder(row,col)?finder(row,col):((row*11+col*7+row*col)%9<4);return `<i class="${filled?'filled':''}"></i>`}).join('')}</div>`}
function renderStreetMap(){const container=$('#action-street-map');if(!container||!window.L)return;streetMap=L.map(container,{zoomControl:false,attributionControl:true}).setView([44.822,20.445],12);L.control.zoom({position:'bottomright'}).addTo(streetMap);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(streetMap);Object.entries(mapLocations).forEach(([name,location])=>{const selected=name===state.mapSelected;const marker=L.circleMarker(location.coords,{radius:selected?10:8,color:'#fff',weight:3,fillColor:selected?'#ff8068':'#b51f45',fillOpacity:1}).addTo(streetMap);marker.bindPopup(`<strong>${name}</strong><br><span>${location.info}</span>`);marker.on('click',()=>{state.mapSelected=name;renderMobile('actions')})});streetMap.invalidateSize()}

function renderMobileList(){
  $('#mobile-screen-list').innerHTML=mobileCatalog.map(group=>`<section class="screen-group"><h3>${group.title}</h3>${group.items.map(([id,label])=>`<button data-mobile-screen="${id}">${label}</button>`).join('')}</section>`).join('');
}

function renderChecklist(){
  const items=screenDecisions[state.mobileScreen]||screenDecisions.home;
  $('#decision-checklist').innerHTML=items.map((item,index)=>`<div class="check-item"><span>${index+1}</span><div><strong>${item[0]}</strong><small>${item[1]}</small></div></div>`).join('');
}

function renderMobile(screen=state.mobileScreen){
  state.mobileScreen=screen;
  const labels=Object.fromEntries(mobileCatalog.flatMap(group=>group.items));
  $('#mobile-flow-label').textContent=labels[screen]||screen;
  $$('#mobile-screen-list [data-mobile-screen]').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===screen));
  const root={actions:'actions','action-detail':'actions',booking:'actions','booking-success':'actions',appointments:'actions',notifications:'notifications',profile:'profile',card:'profile',history:'profile','donation-detail':'profile',corrections:'profile',achievements:'profile',privacy:'profile',pause:'profile',questionnaire:'profile'}[screen]||'home';
  const onboarding=['welcome','registration','verification','link-record'].includes(screen);
  $('#mobile-nav').classList.toggle('hidden',onboarding);
  $$('#mobile-nav [data-mobile-screen]').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===root));
  mobileScreen.innerHTML=mobileTemplates[screen]?.()||mobileTemplates.home();
  if(screen==='actions'&&state.actionsView==='map')requestAnimationFrame(renderStreetMap);
  mobileScreen.scrollTop=0;
  renderChecklist();
  history.replaceState(null,'',`#mobile/${screen}`);
}

