function portalHeader(kicker,title,actions=''){return `<header class="portal-header"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1></div><div class="portal-actions">${actions}</div></header>`}
function metric(label,value,detail,delta=''){return `<article class="metric-card"><span>${label}</span><strong>${value}</strong><small class="${delta?'delta':''}">${detail}</small></article>`}
function panel(title,content,extra='',classes=''){return `<section class="panel ${classes}"><div class="panel-heading"><div><h2>${title}</h2>${extra}</div></div>${content}</section>`}

